/** Favicon: simple shoe mark, no emoji */
function af_favicon_data_uri(): string {
    $svg = rawurlencode('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><path fill="%231a1a1a" d="M4 20c0-2 2-4 6-4h12c2 0 4 1 4 3v2H4v-1zm4-6c0-3 2.5-6 8-6 4 0 6 2 8 4l-2 1c-1.5-1.5-3.5-2.5-6-2.5-4 0-6 2-6 4v1H8v-1.5z"/></svg>');
    return 'data:image/svg+xml,' . $svg;
}
